import java.util.concurrent.atomic.AtomicInteger;

public class Counter {
    private final AtomicInteger count = new AtomicInteger();

    public void increment() {
        count.incrementAndGet();
    }

    public int get() {
        return count.get();
    }
}

import java.util.List;

public class Lists {
    public static <T> void swap(List<T> list, int i, int j) {
        T temp = list.get(i);
        list.set(i, list.get(j));
        list.set(j, temp);
    }
}

import java.io.IOException;
import java.nio.file.*;

public class FileCopy {
    public static void copy(String source, String destination) throws IOException {
        Files.copy(Path.of(source), Path.of(destination), StandardCopyOption.REPLACE_EXISTING);
    }
}

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class ConcurrentWordCount {
    public static Map<String, Long> count(List<String> words) {
        ConcurrentHashMap<String, Long> counts = new ConcurrentHashMap<>();
        words.parallelStream().forEach(word -> counts.merge(word, 1L, Long::sum));
        return counts;
    }
}

